#[derive(Debug)]
pub enum LockFields {}

/// [`CGuarded::Scope`] of a lock over the whole object ([`CGuardedAll`]),
/// reached through [`CGuardedRef::lock`].
#[derive(Debug)]
pub enum LockWhole {}

