pub trait LockScope: sealed::Sealed {}
impl LockScope for LockFields {}
impl LockScope for LockWhole {}

mod sealed {
    pub trait Sealed {}
    impl Sealed for super::LockFields {}
    impl Sealed for super::LockWhole {}
}

