/// writes one generic impl that covers both:
///
/// ```ignore
/// unsafe impl<T> CDrop<T> for LibFree { /* lib_free */ }
/// unsafe impl<T: CCell> CAlloc<T> for LibFree { /* lib_malloc(size_of::<T>()) */ }

